```rust
Commands::Open { paths } => {
    for path in paths {
        if let Ok(url) = Url::parse(path) {
            // scheme handler
        } else {
            let path = Path::new(path);
            let mime = mime_guess::from_path(path).first_raw().unwrap_or_default();
            mime_apps.launch_handler(&mime, &[path.to_str()])?;
        }
    }
}
```
Hmm, `mime_guess` would work for .png.

