import subprocess, os, string
env=dict(os.environ)
env['XDG_DATA_HOME']='/tmp/dd'; env['XDG_CONFIG_HOME']='/tmp/cc'
chars = [chr(i) for i in range(32,127)] + ['\t']
def run(content):
    open('/tmp/cc/mimeapps.list','w').write(content)
    try:
        r=subprocess.run(['/workspace/executable','get','image/png'],capture_output=True,env=env,timeout=5)
        return r.returncode, (r.stdout+r.stderr).decode('utf8','replace')
    except Exception as e:
        return -1, str(e)
# name charset
res=[]
for c in chars:
    rc,out=run('[Default Applications]\nx%sy=1\n' % c)
    res.append((c, rc, out[:120].replace('\n','|')))
print("NAME charset:")
ok=[]; no=[]
for c,rc,out in res:
    if rc==1: ok.append(c)
    else: no.append((c,rc,out))
print("  OK  :", ''.join(ok))
for c,rc,out in no: print("  NO  : %r rc=%d %s" % (c,rc,out))
PYEOF"}

