{"command": "cat > /workspace/src/mime.rs <<'EOF'
//! Minimal re-implementation of the subset of the `mime` crate that handlr relies
//! on: parsing a mime type from a string and rendering it back to a string.
//!
//! The parse errors are rendered with the same wording as the original crate so
//! that the CLI diagnostics are byte for byte identical.

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum MimeParseError {
    /// A "/" separating the type from the subtype was not found.
    MissingSlash,
    /// A "=" separating a parameter name from its value was not found.
    MissingEquals,
    /// A closing quote for a quoted parameter value was not found.
    MissingQuote,
    /// Some other character was found where a token was expected.
    InvalidToken { token: u8, position: usize },
}

impl std::fmt::Display for MimeParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            MimeParseError::MissingSlash => {
                write!(f, "a slash (/) was missing between the type and subtype")
            }
            MimeParseError::MissingEquals => write!(
                f,
                "an equals sign (=) was missing between a parameter and its value"
            ),
            MimeParseError::MissingQuote => {
                write!(f, "a quote (\") was missing from a parameter value")
            }
            MimeParseError::InvalidToken { token, position } => write!(
                f,
                "an invalid token was encountered, {:X} at position {}",
                token, position
            ),
        }
    }
}

fn is_token(b: u8) -> bool {
    matches!(b,
        b'a'..=b'z' | b'A'..=b'Z' | b'0'..=b'9'
        | b'!' | b'#' | b'$' | b'&' | b'\'' | b'+' | b'-' | b'.'
        | b'^' | b'_' | b'`' | b'|' | b'~')
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct Mime {
    /// Lowercased `type/subtype` without any parameters.
    pub essence: String,
    /// Lowercased `name=value` parameters, in the order they appeared.
    pub params: Vec<(String, String)>,
}

impl Mime {
    /// `type/subtype`, without parameters.
    pub fn essence(&self) -> &str {
        &self.essence
    }

    pub fn essence_parts(&self) -> (&str, &str) {
        let idx = self.essence.find('/').unwrap_or(self.essence.len());
        (&self.essence[..idx], &self.essence[idx + 1..])
    }

    /// Full rendering: `type/subtype; name=value; ...`
    pub fn to_string(&self) -> String {
        let mut out = self.essence.clone();
        for (name, value) in &self.params {
            out.push_str("; ");
            out.push_str(name);
            out.push('=');
            out.push_str(value);
        }
        out
    }

    /// Same as `to_string` but only the essence, which is what the default
    /// application database is keyed by.
    pub fn key(&self) -> &str {
        &self.essence
    }
}

/// Split `input` into `type` and `subtype`, lowercasing both.
pub fn parse(input: &str) -> Result<Mime, MimeParseError> {
    let bytes = input.as_bytes();
    let mut pos = 0usize;

    // --- type -----------------------------------------------------------------
    let type_start = pos;
    while pos < bytes.len() && is_token(bytes[pos]) {
        pos += 1;
    }
    if pos == type_start {
        if pos < bytes.len() {
            return Err(MimeParseError::InvalidToken { token: bytes[pos], position: pos });
        }
        return Err(MimeParseError::MissingSlash);
    }
    // A "/" must follow the type. Anything else is an invalid token.
    if pos >= bytes.len() {
        return Err(MimeParseError::MissingSlash);
    }
    if bytes[pos] != b'/' {
        return Err(MimeParseError::InvalidToken { token: bytes[pos], position: pos });
    }
    pos += 1;

    // --- subtype --------------------------------------------------------------
    let subtype_start = pos;
    while pos < bytes.len() && is_token(bytes[pos]) {
        pos += 1;
    }
    if pos == subtype_start {
        if pos >= bytes.len() {
            // e.g. "image/" - the original crate accepts it, handlr does not.
            return Err(MimeParseError::EmptySubtype);
        }
        return Err(MimeParseError::InvalidToken { token: bytes[pos], position: pos });
    }

    let mut params: Vec<(String, String)> = Vec::new();

    loop {
        // After the subtype (or a parameter) only ";" or end of input may follow.
        if pos >= bytes.len() {
            break;
        }
        if bytes[pos] != b';' {
            return Err(MimeParseError::InvalidToken { token: bytes[pos], position: pos });
        }
        pos += 1;
        // Optional whitespace before the parameter name.
        while pos < bytes.len() && (bytes[pos] == b' ' || bytes[pos] == b'\t') {
            pos += 1;
        }
        if pos >= bytes.len() {
            break;
        }
        // --- parameter name ---------------------------------------------------
        let name_start = pos;
        while pos < bytes.len() && is_token(bytes[pos]) {
            pos += 1;
        }
        if pos == name_start {
            return Err(MimeParseError::InvalidToken { token: bytes[pos], position: pos });
        }
        // --- "=" --------------------------------------------------------------
        if pos >= bytes.len() {
            return Err(MimeParseError::MissingEquals);
        }
        if bytes[pos] != b'=' {
            return Err(MimeParseError::InvalidToken { token: bytes[pos], position: pos });
        }
        pos += 1;
        // --- parameter value --------------------------------------------------
        let value: String = if pos < bytes.len() && (bytes[pos] == b'"' || bytes[pos] == b'\'') {
            let quote = bytes[pos];
            pos += 1;
            let start = pos;
            while pos < bytes.len() && bytes[pos] != quote {
                pos += 1;
            }
            if pos >= bytes.len() {
                if quote == b'"' {
                    return Err(MimeParseError::MissingQuote);
                }
                return Err(MimeParseError::MissingQuote);
            }
            let v = String::from_utf8_lossy(&bytes[start..pos]).into_owned();
            pos += 1;
            v
        } else {
            let start = pos;
            while pos < bytes.len() && is_token(bytes[pos]) {
                pos += 1;
            }
            String::from_utf8_lossy(&bytes[start..pos]).into_owned()
        };
        params.push((
            String::from_utf8_lossy(&bytes[name_start..name_start]).into_owned()
                + &lowercase(&input[name_start..pos]),
            String::new(),
        ));
        params.last_mut().unwrap().0 = lowercase(&input[name_start..name_start]);
        // Recompute the name properly: the slice above was only a placeholder.
        params.last_mut().unwrap().0 = {
            let end = {
                let mut e = name_start;
                while e < bytes.len() && is_token(bytes[e]) {
                    e += 1;
                }
                e
            };
            lowercase(&input[name_start..end])
        };
        params.last_mut().unwrap().1 = lowercase(&value);
