        pos += 1;
    }
    if pos == subtype_start && pos < bytes.len() {
        return Err(MimeParseError::InvalidToken { token: bytes[pos], position: pos });
    }

    let mut params: Vec<(String, String)> = Vec::new();

    loop {
        if pos >= bytes.len() {
            break;
        }
        if bytes[pos] != b';' {
            return Err(MimeParseError::InvalidToken { token: bytes[pos], position: pos });
        }
        pos += 1;
        while pos < bytes.len() && bytes[pos] == b' ' {
            pos += 1;
        }
        if pos >= bytes.len() {
            break;
        }
        // --- parameter name ---------------------------------------------------
        let name_start = pos;
        while pos < bytes.len() && is_token(bytes[pos]) {
            pos += 1;
        }
        if pos == name_start {
            return Err(MimeParseError::InvalidToken { token: bytes[pos], position: pos });
        }
        let name_end = pos;
        if pos >= bytes.len() {
            return Err(MimeParseError::MissingEquals);
        }
        if bytes[pos] != b'=' {
            return Err(MimeParseError::InvalidToken { token: bytes[pos], position: pos });
        }
        pos += 1;
        // --- parameter value --------------------------------------------------
        let (value, end): (String, usize) = if pos < bytes.len() && bytes[pos] == b'"' {
            pos += 1;
            let start = pos;
            while pos < bytes.len() && bytes[pos] != b'"' {
                pos += 1;
            }
            if pos >= bytes.len() || pos == start {
                return Err(MimeParseError::MissingQuote);
            }
            (input[start..pos].to_string(), pos + 1)
        } else {
            let start = pos;
            while pos < bytes.len() && is_token(bytes[pos]) {
                pos += 1;
            }
            (input[start..pos].to_string(), pos)
        };
        pos = end;
        if bytes.get(..) != Some(&[]) {
            // quoted values may be followed by optional whitespace
        }
        if bytes.get(pos.wrapping_sub(0)) != None {
            // no-op, kept for clarity
        }
        if was_quoted(pos, end) {
            while pos < bytes.len() && bytes[pos] == b' ' {
                pos += 1;
            }
        }
