//! A small, self contained re-implementation of the subset of the `mime` crate
//! that handlr depends upon: parsing a mime type from a string and rendering it
//! back.  The diagnostics use exactly the same wording as the upstream crate so
//! that the CLI output matches byte for byte.

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum MimeParseError {
    /// No `/` separating the type from the subtype.
    MissingSlash,
    /// No `=` separating a parameter name from its value.
    MissingEquals,
    /// Unterminated (or empty) quoted parameter value.
    MissingQuote,
    /// Unexpected byte at the given (byte) position.
    InvalidToken { token: u8, position: usize },
}

impl std::fmt::Display for MimeParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            MimeParseError::MissingSlash => {
                write!(f, "a slash (/) was missing between the type and subtype")
            }
            MimeParseError::MissingEquals => write!(
                f,
                "an equals sign (=) was missing between a parameter and its value"
            ),
            MimeParseError::MissingQuote => {
                write!(f, "a quote (\") was missing from a parameter value")
            }
            MimeParseError::InvalidToken { token, position } => write!(
                f,
                "an invalid token was encountered, {:X} at position {}",
                token, position
            ),
        }
    }
}

/// RFC 7230 `token` character set: the upstream crate uses it for the type, the
/// subtype, parameter names and unquoted parameter values.
fn is_token(b: u8) -> bool {
    matches!(b,
        b'a'..=b'z' | b'A'..=b'Z' | b'0'..=b'9'
        | b'!' | b'#' | b'$' | b'&' | b'\'' | b'+' | b'-' | b'.'
        | b'^' | b'_' | b'`' | b'|' | b'~')
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct Mime {
    /// Lowercased `type/subtype`.
    pub essence: String,
    /// Lowercased parameters in the order they appeared.
    pub params: Vec<(String, String)>,
}

impl Mime {
    pub fn essence(&self) -> &str {
        &self.essence
    }

    pub fn essence_parts(&self) -> (&str, &str) {
        match self.essence.find('/') {
            Some(i) => (&self.essence[..i], &self.essence[i + 1..]),
            None => (self.essence.as_str(), ""),
        }
    }

    /// Rendering including parameters, lowercased.
    pub fn to_full_string(&self) -> String {
        let mut out = self.essence.clone();
        for (name, value) in &self.params {
            out.push_str("; ");
            out.push_str(name);
            out.push('=');
            out.push_str(value);
        }
        out
    }

    /// handlr rejects mimes whose subtype is empty (`image/`).
    pub fn has_empty_subtype(&self) -> bool {
        self.essence_parts().1.is_empty()
    }
}

pub fn lowercase(s: &str) -> String {
    s.to_lowercase()
}

pub fn parse(input: &str) -> Result<Mime, MimeParseError> {
    let bytes = input.as_bytes();
    let mut pos = 0usize;

    // --- type -----------------------------------------------------------------
    let type_start = pos;
    while pos < bytes.len() && is_token(bytes[pos]) {
        pos += 1;
    }
    if pos == type_start {
        return if pos < bytes.len() {
            Err(MimeParseError::InvalidToken { token: bytes[pos], position: pos })
        } else {
            Err(MimeParseError::MissingSlash)
        };
    }
    if pos >= bytes.len() {
        return Err(MimeParseError::MissingSlash);
    }
    if bytes[pos] != b'/' {
        return Err(MimeParseError::InvalidToken { token: bytes[pos], position: pos });
    }
    pos += 1;

    // --- subtype --------------------------------------------------------------
    let subtype_start = pos;
    while pos < bytes.len() && is_token(bytes[pos]) {
        pos += 1;
    }
    let subtype_end = pos;
    if pos == subtype_start && pos < bytes.len() {
        return Err(MimeParseError::InvalidToken { token: bytes[pos], position: pos });
    }

    let mut params: Vec<(String, String)> = Vec::new();
    let mut quoted = false;

    loop {
        if pos >= bytes.len() {
            break;
        }
        if bytes[pos] != b';' {
            return Err(MimeParseError::InvalidToken { token: bytes[pos], position: pos });
        }
        pos += 1;
        while pos < bytes.len() && bytes[pos] == b' ' {
            pos += 1;
        }
        if pos >= bytes.len() {
            break;
        }
        // --- parameter name ---------------------------------------------------
        let name_start = pos;
        while pos < bytes.len() && is_token(bytes[pos]) {
            pos += 1;
        }
        if pos == name_start {
            return Err(MimeParseError::InvalidToken { token: bytes[pos], position: pos });
        }
        let name_end = pos;
        if pos >= bytes.len() {
            return Err(MimeParseError::MissingEquals);
        }
        if bytes[pos] != b'=' {
            return Err(MimeParseError::InvalidToken { token: bytes[pos], position: pos });
        }
        pos += 1;
        // --- parameter value --------------------------------------------------
        let (value, end): (String, usize) = if pos < bytes.len() && bytes[pos] == b'"' {
            quoted = true;
            pos += 1;
            let start = pos;
            while pos < bytes.len() && bytes[pos] != b'"' {
                pos += 1;
            }
            if pos >= bytes.len() || pos == start {
                return Err(MimeParseError::MissingQuote);
            }
            (input[start..pos].to_string(), pos + 1)
        } else {
            quoted = false;
            let start = pos;
            while pos < bytes.len() && is_token(bytes[pos]) {
                pos += 1;
            }
            (input[start..pos].to_string(), pos)
        };
        pos = end;
        // A quoted value may be followed by optional whitespace; an unquoted one
        // may not.
        if quoted {
            while pos < bytes.len() && bytes[pos] == b' ' {
                pos += 1;
            }
        }
        params.push((lowercase(&input[name_start..name_end]), lowercase(&value)));
    }

    let essence = format!(
        "{}/{}",
        lowercase(&input[type_start..subtype_start - 1]),
        lowercase(&input[subtype_start..subtype_end]),
    );
    Ok(Mime { essence, params })
}
