//! ASCII table rendering, matching the layout produced by the `tabular` crate
//! with its default style and a maximum width of 80 columns.

use std::cmp::max;

const MAX_WIDTH: usize = 80;

const TOP_LEFT: char = 'â';
const TOP_MID: char = 'â';
const TOP_RIGHT: char = 'â';
const BOTTOM_LEFT: char = 'â';
const BOTTOM_MID: char = 'â';
const BOTTOM_RIGHT: char = 'â';
const MIDDLE_LEFT: char = '';
const MIDDLE_MID: char = '';
const MIDDLE_RIGHT: char = '';
const HORIZONTAL: char = 'â';

pub struct Table {
    rows: Vec<Vec<String>>,
}

impl Table {
    pub fn new() -> Table {
        Table { rows: Vec::new() }
    }

    pub fn push(&mut self, row: Vec<String>) {
        self.rows.push(row);
    }

    pub fn is_empty(&self) -> bool {
        self.rows.is_empty()
    }

    fn ncols(&self) -> usize {
        self.rows.iter().map(|r| r.len()).max().unwrap_or(0)
    }

    /// Natural (untruncated) width of every column.
    fn natural(&self) -> Vec<usize> {
        let n = self.ncols();
        let mut widths = vec![0usize; n];
        for row in &self.rows {
            for (i, cell) in row.iter().enumerate() {
                widths[i] = max(widths[i], cell.chars().count());
            }
        }
        widths
    }

    pub fn render(&self) -> String {
        if self.rows.is_empty() {
            // `tabular` renders a table without rows as a single empty column.
            let mut s = String::new();
            s.push(TOP_LEFT);
            s.push(HORIZONTAL);
            s.push(HORIZONTAL);
            s.push(TOP_RIGHT);
            s.push('\n');
            s.push(MIDDLE_LEFT);
            s.push(' ');
            s.push(' ');
            s.push(MIDDLE_RIGHT);
            s.push('\n');
            s.push(BOTTOM_LEFT);
            s.push(HORIZONTAL);
            s.push(HORIZONTAL);
            s.push(BOTTOM_RIGHT);
            s.push('\n');
            return s;
        }
        let n = self.ncols();
        let natural = self.natural();
        let overhead = (n + 1) + 2 * n;
        let mut widths = natural.clone();
        if natural.iter().sum::<usize>() + overhead > MAX_WIDTH {
            widths = distribute(&natural, MAX_WIDTH - overhead);
        }

        let mut out = String::new();
        border(&mut out, &widths, TOP_LEFT, TOP_MID, TOP_RIGHT);
        for row in &self.rows {
            out.push(MIDDLE_LEFT);
            for (i, w) in widths.iter().enumerate() {
                if i > 0 {
                    out.push(MIDDLE_MID);
                }
                let cell = row.get(i).cloned().unwrap_or_default();
                out.push(' ');
                out.push_str(&fit(&cell, *w));
                out.push(' ');
