fn distribute(natural: &[usize], available: usize) -> Vec<usize> {
    let n = natural.len();
    if n == 0 {
        return Vec::new();
    }
    let mut widths = natural.to_vec();
    for _ in 0..1000 {
        let total: usize = widths.iter().sum();
        if total <= available {
            break;
