//! ASCII table rendering, matching the layout produced by the `tabular` crate
//! with its default style and a maximum width of 80 columns.

use std::cmp::max;

const MAX_WIDTH: usize = 80;

const TOP_LEFT: char = 'â';
const TOP_MID: char = 'â';
const TOP_RIGHT: char = 'â';
const BOTTOM_LEFT: char = 'â';
const BOTTOM_MID: char = 'â';
const BOTTOM_RIGHT: char = 'â';
const MIDDLE_LEFT: char = '';
const MIDDLE_MID: char = '';
const MIDDLE_RIGHT: char = '';
const HORIZONTAL: char = 'â';

pub struct Table {
    rows: Vec<Vec<String>>,
}

impl Table {
    pub fn new() -> Table {
        Table { rows: Vec::new() }
    }

    pub fn push(&mut self, row: Vec<String>) {
        self.rows.push(row);
    }

    pub fn is_empty(&self) -> bool {
        self.rows.is_empty()
    }

    fn ncols(&self) -> usize {
        self.rows.iter().map(|r| r.len()).max().unwrap_or(0)
    }

    /// Natural (untruncated) width of every column.
    fn natural(&self) -> Vec<usize> {
        let n = self.ncols();
        let mut widths = vec![0usize; n];
        for row in &self.rows {
            for (i, cell) in row.iter().enumerate() {
                widths[i] = max(widths[i], cell.chars().count());
            }
        }
        widths
    }

    pub fn render(&self) -> String {
        if self.rows.is_empty() {
            // `tabular` renders a table without rows as a single empty column.
            let mut s = String::new();
            s.push(TOP_LEFT);
            s.push(HORIZONTAL);
            s.push(HORIZONTAL);
            s.push(TOP_RIGHT);
            s.push('\n');
            s.push(MIDDLE_LEFT);
            s.push(' ');
            s.push(' ');
            s.push(MIDDLE_RIGHT);
            s.push('\n');
            s.push(BOTTOM_LEFT);
            s.push(HORIZONTAL);
            s.push(HORIZONTAL);
            s.push(BOTTOM_RIGHT);
            s.push('\n');
            return s;
        }
        let n = self.ncols();
        let natural = self.natural();
        let overhead = (n + 1) + 2 * n;
        let mut widths = natural.clone();
        if natural.iter().sum::<usize>() + overhead > MAX_WIDTH {
            widths = distribute(&natural, MAX_WIDTH - overhead);
        }

        let mut out = String::new();
        border(&mut out, &widths, TOP_LEFT, TOP_MID, TOP_RIGHT);
        for row in &self.rows {
            out.push(MIDDLE_LEFT);
            for (i, w) in widths.iter().enumerate() {
                if i > 0 {
                    out.push(MIDDLE_MID);
                }
                let cell = row.get(i).cloned().unwrap_or_default();
                out.push(' ');
                out.push_str(&fit(&cell, *w));
                out.push(' ');
            }
            out.push(MIDDLE_RIGHT);
            out.push('\n');
        }
        border(&mut out, &widths, BOTTOM_LEFT, BOTTOM_MID, BOTTOM_RIGHT);
        out
    }
}

fn border(out: &mut String, widths: &[usize], left: char, mid: char, right: char) {
    out.push(left);
    for (i, w) in widths.iter().enumerate() {
        if i > 0 {
            out.push(mid);
        }
        for _ in 0..w + 2 {
            out.push(HORIZONTAL);
        }
    }
    out.push(right);
    out.push('\n');
}

/// Truncate a cell to `width` characters, marking the cut with a `+`.
fn fit(cell: &str, width: usize) -> String {
    let chars: Vec<char> = cell.chars().collect();
    if chars.len() <= width {
        let mut s: String = chars.iter().collect();
        for _ in chars.len()..width {
            s.push(' ');
        }
        return s;
    }
    let mut s: String = chars[..width - 1].iter().collect();
    s.push('+');
    s
}

fn second_max(widths: &[usize]) -> usize {
    let mut sorted = widths.to_vec();
    sorted.sort_unstable_by(|a, b| b.cmp(a));
    sorted.get(1).copied().unwrap_or_else(|| widths.iter().copied().max().unwrap_or(0))
}

/// Hand out `available` columns of content between the columns.  Columns are
/// first shrunk towards each other (the widest one is trimmed to the width of
/// the runner up, or to whatever is left over) until everything fits, and any
/// remaining slack is given back to the leading columns.
fn distribute(natural: &[usize], available: usize) -> Vec<usize> {
    let n = natural.len();
    if n == 0 {
        return Vec::new();
    }
    let mut widths = natural.to_vec();
    for _ in 0..1000 {
        let total: usize = widths.iter().sum();
        if total <= available {
            break;
        }
        let largest = widths.iter().copied().max().unwrap_or(0);
        let rest = total - largest;
        let target = if largest == second_max(&widths) {
            largest - 1
        } else {
            max(second_max(&widths).min(largest), rest)
        };
        for w in widths.iter_mut() {
            if *w > target {
                *w = max(target, 0);
            }
        }
        if widths.iter().sum::<usize>() == total {
            // No progress is possible (single column that is too wide).
            break;
        }
    }
    let mut slack = available.saturating_sub(widths.iter().sum());
    for i in 0..n {
        while slack > 0 && widths[i] < natural[i] {
            widths[i] += 1;
            slack -= 1;
        }
    }
    widths
}
